template.script:
            document.addEventListener('DOMContentLoaded', function () {
                if (typeof L === 'undefined') return;
                var mapEl = document.getElementById('fs-stations-map');
                if (!mapEl) return;
                var map = L.map('fs-stations-map');
                L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                    maxZoom: 18,
                    attribution: '&copy; OpenStreetMap contributors'
                }).addTo(map);
                var stations = ;
                var markers = [];
                stations.forEach(function(s) {
                    var lat = parseFloat(s.latitude), lng = parseFloat(s.longitude);
                    if (!isFinite(lat) || !isFinite(lng)) return;
                    var m = L.marker([lat, lng]).addTo(map);
                    var saved = (s.money_saved_display != null && s.money_saved_display !== '')
                        ? s.money_saved_display
                        : (s.money_saved_eur != null ? Math.round(Number(s.money_saved_eur)) : '\u2014');
                    var info = (s.info || s.description || '');
                    function esc(t) {
                        return String(t == null ? '' : t)
                            .replace(/&/g, '&amp;')
                            .replace(/\x3c/g, '&lt;')
                            .replace(/\x3e/g, '&gt;')
                            .replace(/"/g, '&quot;');
                    }
                    var html = '' + esc(s.name || 'Station') + '
'
                        + esc(s.location || '') + '
'
                        + esc(s.capacity_kwp || 0) + ' kWp
'
                        + 'Poupança estimada: ' + esc(saved) + ' EUR/ano';
                    if (s.savings_is_indicative) {
                        html += ' (indicativa)';
                    }
                    if (info) {
                        html += '
Descrição: ' + esc(info);
                    }
                    if (s.website) {
                        var w = String(s.website);
                        if (!/^https?:\/\//i.test(w)) { w = 'https://' + w; }
                        html += '
Website';
                    }
                    m.bindPopup(html);
                    markers.push(m);
                });
                if (markers.length) {
                    map.fitBounds(L.featureGroup(markers).getBounds().pad(0.15));
                } else {
                    map.setView([38.7223,-9.1393], 5);
                }
            });
